// Builds the isometric equipment figures: node tools/iso/build.mjs [id ...]
// For each tools/iso/figures/<id>.mjs it draws the static SVG with the vendored Anatomy kit and writes
// iso-fig-<id>.js at the repo root: the SVG, the projection basis, the morph keyframes and the hand-written ES5
// driver from tools/iso/figures/<id>.driver.js. It also writes iso-figures.css (the kit's ISO_CSS rules, scoped to
// .smd-iso and themed for the app, plus tools/iso/card.css). The generated files are committed; the app never runs
// the kit. --check exits non-zero if a generated file is out of date.
import { readFileSync, writeFileSync, readdirSync, existsSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { k, basisOf } from "./lib.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..", "..");
const args = process.argv.slice(2), check = args.includes("--check");
const only = args.filter((a) => !a.startsWith("--"));
const ids = readdirSync(join(HERE, "figures")).filter((f) => /^[a-z0-9-]+\.mjs$/.test(f)).map((f) => f.slice(0, -4)).filter((id) => !only.length || only.includes(id));
let stale = 0;
const round = (v) => JSON.parse(JSON.stringify(v, (key, x) => (typeof x === "number" ? Math.round(x * 100) / 100 : x)));

function put(file, text) {
  const path = join(ROOT, file);
  const old = existsSync(path) ? readFileSync(path, "utf8") : null;
  if (old === text) return;
  if (check) { console.error("out of date: " + file); stale++; return; }
  writeFileSync(path, text);
  console.log("wrote " + file + " (" + Math.round(text.length / 1024) + " KB)");
}

// The kit's rules, with its theme block replaced by the app's: light by default, dark under body.dark or an
// explicit data-theme="dark" (the product page).
function css() {
  const kit = readFileSync(join(HERE, "kit", "iso.css"), "utf8");
  const rules = kit.replace(/^\.iso\{[\s\S]*?\n\}\n\.iso\[data-theme="light"\]\{[\s\S]*?\n\}\n/, "");
  if (rules === kit) throw new Error("kit/iso.css theme block not found: update tools/iso/build.mjs");
  const vars = (block) => block.match(/\{([\s\S]*?)\n\}/)[1].trim();
  const dark = vars(kit.match(/^\.iso\{[\s\S]*?\n\}/m)[0]), light = vars(kit.match(/\.iso\[data-theme="light"\]\{[\s\S]*?\n\}/)[0]);
  const shared = dark.split(/;\s*/).filter((d) => /--anatomy-(weight|ease|mono)/.test(d)).join(";");
  return "/* StewardMD isometric figures. Generated by tools/iso/build.mjs from tools/iso/kit/iso.css (Anatomy kit, MIT) and tools/iso/card.css. Do not edit. */\n" +
    ".smd-iso{" + light + ";" + shared + "}\n" +
    "body.dark .smd-iso:not([data-theme=\"light\"]),.smd-iso[data-theme=\"dark\"]{" + dark + "}\n" +
    rules.replace(/\.iso-figure\{[^}]*\}\n|\.iso-plate[^\n]*\n|\.iso-legend[^\n]*\n|\.iso-keys[^\n]*\n|\.iso-key\{[^\n]*\n|\.iso-swatch[^\n]*\n|@media \(max-width:560px\)[^\n]*\n/g, "") +
    readFileSync(join(HERE, "card.css"), "utf8");
}

for (const id of ids) {
  const mod = await import(pathToFileURL(join(HERE, "figures", id + ".mjs")).href);
  const f = mod.default();
  const svg = k.figureSvg({ width: f.width, height: f.height, label: f.label, body: f.body });
  const data = {
    id, fig: f.fig, title: f.title, hint: f.hint, caption: f.caption, keys: f.keys || [], sources: f.sources || [], model: f.model || "",
    review: f.review || "ai_drafted", basis: basisOf(f.P), morphs: f.morphs || {}, data: round(f.data || {}), svg,
  };
  for (const text of [f.title, f.hint, f.caption, f.label, f.model, ...(f.keys || []).map((x) => x.label), ...(f.sources || [])]) {
    if (/[–—]/.test(text || "")) throw new Error(id + ": no en or em dash in figure text: " + text);
  }
  const driver = readFileSync(join(HERE, "figures", id + ".driver.js"), "utf8");
  const out = "/* StewardMD isometric figure \"" + id + "\". Generated by tools/iso/build.mjs from tools/iso/figures/" + id + ".mjs (drawing, Anatomy kit, MIT)\n" +
    "   and " + id + ".driver.js (the ES5 model and motion). Do not edit; rebuild with node tools/iso/build.mjs " + id + ". */\n" +
    "(function (G) {\n\"use strict\";\nvar FIG = " + JSON.stringify(data) + ";\n" + driver.trim() + "\nFIG.driver = DRIVER;\n" +
    "if (typeof module !== \"undefined\" && module.exports) module.exports = FIG;\nelse (G.SMD_ISO_FIGS = G.SMD_ISO_FIGS || {})[FIG.id] = FIG;\n" +
    "})(typeof window !== \"undefined\" ? window : this);\n";
  put("iso-fig-" + id + ".js", out);
}
if (!only.length) put("iso-figures.css", css());
if (stale) process.exit(1);
